const menuButton=document.querySelector('.menu-toggle');
const nav=document.querySelector('.nav');
menuButton?.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation');menuButton.focus()}});
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('.flavour').forEach(item=>{item.hidden=button.dataset.filter!=='all'&&item.dataset.category!==button.dataset.filter;if(!item.hidden)count++});document.querySelector('#filter-status').textContent=`${count} flavour ideas shown`;}));
const form=document.querySelector('#enquiry-form');
if(form){const date=form.elements.date;const now=new Date();date.min=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;const category=new URLSearchParams(location.search).get('collection');if([...form.elements.collection.options].some(o=>o.value===category))form.elements.collection.value=category;
form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const values=new FormData(form);document.querySelector('#message-preview').value=`Hello Adeela, I would love to enquire about ${values.get('collection')}.\n\nName: ${values.get('name')}\nEmail: ${values.get('email')}\nCelebration date: ${values.get('date')}\nGuests / cupcakes: ${values.get('guests')||'To discuss'}\n\n${values.get('message')}\n\nPlease let me know your availability and the next steps. Thank you!`;const result=document.querySelector('#enquiry-result');result.hidden=false;result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});document.querySelector('#result-title').focus();});
document.querySelector('#copy-enquiry').addEventListener('click',async()=>{const text=document.querySelector('#message-preview');try{await navigator.clipboard.writeText(text.value);document.querySelector('#copy-status').textContent='Copied. Open Instagram and paste your message to @bakedbyadeela.'}catch{text.focus();text.select();document.querySelector('#copy-status').textContent='Select and copy the message above, then paste it into Instagram.'}});}
